"""INSTALL1c steps 6 and 7: the cards "what was chosen and why" and the matrix of machines, both generated by this test.

The test builds the machines from recorded fixtures (tests/fixtures/detect), asks autofit_api.choose() for the choice and
writes two files (default folder ~/Desktop/AI/reports/install1c, or SHURA_REPORT_DIR):
  cards.md   the card (installer/universal/card.py) of three machines: RX 7800 XT / ROCm, laptop Intel+NVIDIA, CPU only
  matrix.md  one row per machine: expected backend, model with quant, kind of mode (written below BEFORE the first run)
             against the actual choice. A row that differs from its expectation FAILS the test, except the rows marked
             KNOWN_WRONG: for them the expectation is "ожидаемо неверно: исправляет AUTOFIT1" and the actual value is shown
             next to it, so the day AUTOFIT1 fixes the planner the change is visible in the table (the test does not fail).
Do not edit matrix.md by hand: it is regenerated at every run.

No network, no GPU, no model, no real home: HOME, TMPDIR and SHURA_HOME point into /dev/shm/INSTALL1c.
Run: python3 -B -m unittest tests.test_install_matrix_generated
"""
import json
import os
import pwd
import socket
import sys
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "installer"))
sys.path.insert(0, str(ROOT / "tests"))
sys.path.insert(0, str(ROOT))
from universal import autofit_api as A, card  # noqa: E402
import test_install_dryrun_matrix as DM  # noqa: E402

DM.SCRATCH = Path("/dev/shm/INSTALL1c") if Path("/dev/shm").is_dir() else DM.SCRATCH
DM.MACHINES["laptop_rtx3050_6g"] = ("../laptop_rtx3050_6g_16g", "extra_laptop_intel_nvidia")   # fixture folder outside matrix/
GiB = 1024 ** 3
CAT = json.loads((ROOT / "catalog/models.json").read_text())
MODEL = "tiel-coder-35b-a3b-mtp"
REPORT_DIR = Path(os.environ.get("SHURA_REPORT_DIR") or Path(pwd.getpwuid(os.getuid()).pw_dir) / "Desktop/AI/reports/install1c")
WRONG = "ожидаемо неверно: исправляет AUTOFIT1"

# EXPECTATIONS, written before the first run. key: (label, fixture machine, backend, model/quant, kind of mode, known wrong).
# The RTX 3050 6 GiB laptop (16 GiB RAM) was expected to get the lighter quant; the planner today refuses (the only catalog
# model needs 5.1 GiB of VRAM before any expert, 4.0 GiB is free; 20.2 GiB of RAM needed, 10.0 GiB available): known wrong.
# For the known-wrong rows the planner gives the value in the last field today; the right value is for AUTOFIT1 to decide.
ROWS = [
    ("RX 7800 XT 16 ГБ",                        "rx7800xt",            "hip",    f"{MODEL}/IQ4_XS",   "hybrid", None),
    ("ноутбук Intel iGPU + NVIDIA",             "laptop_intel_nvidia", "cuda",   f"{MODEL}/IQ4_XS",   "hybrid", f"{MODEL}/IQ4_XS"),
    ("только CPU",                              "cpu_only",            "cpu",    f"{MODEL}/Q3_K_XL",  "cpu",    None),
    ("NVIDIA 8 ГБ",                             "rtx_8g",              "cuda",   f"{MODEL}/IQ4_XS",   "hybrid", f"{MODEL}/IQ4_XS"),
    ("NVIDIA 12 ГБ",                            "rtx_12g",             "cuda",   f"{MODEL}/Q3_K_XL",  "hybrid", f"{MODEL}/Q3_K_XL"),
    ("NVIDIA 16 ГБ",                            "rtx_16g",             "cuda",   f"{MODEL}/IQ4_XS",   "hybrid", f"{MODEL}/IQ4_XS"),
    ("ноутбук RTX 3050 6 ГБ",                  "laptop_rtx3050_6g",   "cuda",   f"{MODEL}/Q3_K_XL",  "hybrid", "нет модели"),
    ("машина без cgroup v2",                    "rx7800xt",            "hip",    f"{MODEL}/IQ4_XS",   "hybrid", None),
    ("машина без места на диске",               "rx7800xt",            "нет",    "нет модели",        "none",   None),
    ("машина без компилятора на пути CPU",      "cpu_only",            "cpu",    f"{MODEL}/Q3_K_XL",  "cpu",    None),
]
CARDS = [("RX 7800 XT 16 ГБ, ROCm", "rx7800xt"), ("ноутбук Intel iGPU + NVIDIA", "laptop_intel_nvidia"), ("только процессор", "cpu_only")]
RESULTS = {}      # row label -> dict(actual, ok, status)
CARD_TEXTS = {}


class Base(unittest.TestCase):
    def machine(self, name, *, free=None, tools=True, drop=()):
        """(hw, choice, sandbox) of a fixture machine as the installer's own detection sees it."""
        box = DM.Sandbox(self, name, free=free, tools=tools, drop_files=drop)
        with box.active():
            hw = box.detect()
        return hw, A.choose(hw, CAT), box


def actual_of(c):
    if not c.ok:
        return {"backend": "нет", "model": "нет модели", "mode": "none"}
    return {"backend": c.backend, "model": f"{c.model_id}/{c.quant}", "mode": c.mode}


class MatrixRows(Base):
    def run_row(self, label, extra=None):
        _, name, backend, model, mode, wrong = next(r for r in ROWS if r[0] == label)
        kw = extra or {}
        hw, c, box = self.machine(name, **kw.get("machine", {}))
        act = actual_of(c)
        RESULTS[label] = {"actual": act, "status": "FAIL"}
        if kw.get("check"):
            kw["check"](self, hw, c, box)
        if wrong != "нет модели":     # a known-wrong row where the planner refuses today has no backend or mode to compare
            self.assertEqual(act["backend"], backend, f"{label}: backend")    # the backend is not in the known-wrong set
            self.assertEqual(act["mode"], mode, f"{label}: kind of mode")
        if wrong:
            still = act["model"] == wrong
            RESULTS[label]["status"] = WRONG + (" (всё ещё так)" if still else " (ЗНАЧЕНИЕ ИЗМЕНИЛОСЬ: AUTOFIT1 исправил? обновить)")
        else:
            self.assertEqual(act["model"], model, f"{label}: model/quant")
            RESULTS[label]["status"] = "совпало"

    def test_1_rx7800xt(self):
        self.run_row("RX 7800 XT 16 ГБ")

    def test_2_laptop(self):
        def check(t, hw, c, box):
            intel = [g for g in hw["system"]["gpus_all"] if g["vendor"] == "intel"]
            t.assertTrue(intel and intel[0]["display"] is True)       # the Intel iGPU draws the screen, NVIDIA computes
        self.run_row("ноутбук Intel iGPU + NVIDIA", {"check": check})

    def test_3_cpu_only(self):
        self.run_row("только CPU")

    def test_4_nvidia_8(self):
        self.run_row("NVIDIA 8 ГБ")

    def test_5_nvidia_12(self):
        self.run_row("NVIDIA 12 ГБ")

    def test_6_nvidia_16(self):
        self.run_row("NVIDIA 16 ГБ")

    def test_6b_laptop_rtx3050_6g(self):
        def check(t, hw, c, box):
            t.assertEqual(hw["gpus"][0]["vram_total"] // 1024 ** 2, 6144)
            intel = [g for g in hw["system"]["gpus_all"] if g["vendor"] == "intel"]
            t.assertTrue(intel and intel[0]["display"] is True)
        self.run_row("ноутбук RTX 3050 6 ГБ", {"check": check})

    def test_7_no_cgroup_v2(self):
        def check(t, hw, c, box):
            t.assertIs(hw["system"]["cgroup_v2"], False)
        self.run_row("машина без cgroup v2", {"machine": {"drop": ("/sys/fs/cgroup/cgroup.controllers",)}, "check": check})

    def test_8_no_disk(self):
        def check(t, hw, c, box):
            t.assertFalse(c.ok)
            t.assertIn("диск", c.reasons[0])
            t.assertIsNone(c.model_id)
        self.run_row("машина без места на диске", {"machine": {"free": 5 * GiB}, "check": check})

    def test_9_no_compiler_on_cpu_path(self):
        """The CPU path uses the ready upstream binary: no cmake/ninja/compiler is needed, so the choice does not change,
        the dry run ends with exit 0, shows no traceback and asks for no sudo."""
        def check(t, hw, c, box):
            code, text, exc = box.cli("--dry-run", "--backend", "cpu")
            DM.no_traceback(t, exc, text, "no compiler, cpu path")
            t.assertEqual(code, 0, text)
            t.assertNotIn("sudo", text.lower())
            t.assertNotIn("missing", text.lower())
        self.run_row("машина без компилятора на пути CPU", {"machine": {"tools": {"git"}}, "check": check})


class Cards(Base):
    def test_cards(self):
        host = socket.gethostname()
        user = os.environ.get("USER") or Path.home().name
        for title, name in CARDS:
            hw, c, _ = self.machine(name)
            self.assertTrue(c.ok, c.reasons)
            text = card.card_text(title, hw, c)
            CARD_TEXTS[title] = text
            for need in ("shura uninstall", "прогноз, не измерено", "--model-id", "--quant", c.model_id, c.quant,
                         "Главное ограничение", "Отвергнутая альтернатива"):
                self.assertIn(need, text, f"{title}: {need}")
            self.assertEqual(text, card.card_text(title, hw, c))                   # deterministic
            for private in (host, user):
                self.assertNotIn(private, text, f"{title}: private name in the card")
            self.assertNotIn("Traceback", text)
            self.assertIn("Что значат слова «цель» и «комфортно»", text)
            self.assertIn("Порядок бэкендов на этой машине: " + ", затем ".join(card.BACKEND_NAMES[b] for b in c.backend_order), text)
            self.assertIn("удаляет всё, что установка записала в журнал", text)
            self.assertIn("shura uninstall --models", text)
            kv = card._kv_cache(c)
            if kv in card.KV_EXPLAIN:
                self.assertIn(card.KV_EXPLAIN[kv], text)
            self.assertNotIn("ВНИМАНИЕ", text if c.speed_range["mid"] >= 15 else "")
            if c.speed_range["mid"] < 15:
                self.assertIn("ВНИМАНИЕ", text)
            if c.alternative:
                self.assertIn(str(c.alternative["tok_s"]), text)
            self.assertIn(f"{c.speed_range['low']}", text)
        # explanations of the words: turbo3, q4_0, the planner score, the slow-speed warning
        hw, c, _ = self.machine("rx7800xt")
        import copy
        slow = copy.deepcopy(c)
        slow.speed_range = {"low": 6.0, "mid": 9.0, "high": 12.0, "measured": False}
        slow.reasons = [r.replace("q4_0", "turbo3") for r in slow.reasons]
        slow.alternative = dict(slow.alternative or {}, why_not="счёт планировщика ниже: 30 против 32 tok/s", tok_s=30, model_id="m", quant="Q",
                                backend="hip", context=1000, mode="hybrid")
        t = card.card_text("медленная", hw, slow)
        self.assertIn("ВНИМАНИЕ: ожидаемая скорость ниже 15 tok/s", t)
        self.assertIn("«Счёт планировщика» - число", t)
        if card._kv_cache(slow) == "turbo3":
            self.assertIn("turbo3: очень сильное сжатие", t)
        self.assertNotIn("ВНИМАНИЕ", card.card_text("быстрая", hw, c))
        # a machine where nothing fits: a card still reads, says nothing is installed
        hw, c, _ = self.machine("rx7800xt", free=5 * GiB)
        text = card.card_text("без места", hw, c, rejected_note="Освободите место и повторите.")
        self.assertIn("ничего не скачает", text)
        self.assertIn("диск", text)


def tearDownModule():
    REPORT_DIR.mkdir(parents=True, exist_ok=True)
    lines = ["# Матрица установки (порождена тестом tests/test_install_matrix_generated.py, руками не править)", "",
             "Ожидания записаны в тесте до прогона. Строка с пометкой «ожидаемо неверно» показывает фактическое значение рядом.",
             "", "| машина | ожидаемый бэкенд | ожидаемая модель/квант | ожидаемый вид режима | фактически: бэкенд | фактически: модель/квант | фактически: вид | итог |",
             "|---|---|---|---|---|---|---|---|"]
    for label, _name, backend, model, mode, wrong in ROWS:
        r = RESULTS.get(label)
        exp_model = f"{WRONG}; сегодня {wrong}" if wrong else model
        if r:
            a = r["actual"]
            lines.append(f"| {label} | {backend} | {exp_model} | {mode} | {a['backend']} | {a['model']} | {a['mode']} | {r['status']} |")
        else:
            lines.append(f"| {label} | {backend} | {exp_model} | {mode} | - | - | - | не выполнено |")
    (REPORT_DIR / "matrix.md").write_text("\n".join(lines) + "\n")
    if CARD_TEXTS:
        body = ["# Карточки «что выбрано и почему» (порождены тестом tests/test_install_matrix_generated.py)", ""]
        body += ["\n".join([t, "", "---", ""]) for t in CARD_TEXTS.values()]
        (REPORT_DIR / "cards.md").write_text("\n".join(body))


if __name__ == "__main__":
    unittest.main()
